import importBansJson from '@/tariff-data/calculator/import-bans.json';
import type { TariffImportBan, TariffMeasureSource } from '@/types/tariff-calculator-measures';

// Import bans (issue #1796): src/tariff-data/calculator/import-bans.json, generated by
// src/scripts/tariff-calculator/build-import-bans.py from measures_country_actions.py. Bundled with
// the app (static import) and pure, like confirmation-facts.ts. Malformed entries are dropped with a warning.

function isSource(v: unknown): v is TariffMeasureSource {
  if (typeof v !== 'object' || v === null) return false;
  const s = v as Record<string, unknown>;
  return typeof s.citation === 'string' && typeof s.url === 'string' && typeof s.published === 'string';
}

function isStringArray(v: unknown): v is string[] {
  return Array.isArray(v) && v.every((x) => typeof x === 'string');
}

function isBan(v: unknown): v is TariffImportBan {
  if (typeof v !== 'object' || v === null) return false;
  const b = v as Record<string, unknown>;
  const c = b.conditions as Record<string, unknown> | undefined;
  return (
    typeof b.id === 'string' &&
    isStringArray(b.countries) &&
    isStringArray(b.coveragePrefixes) &&
    b.coveragePrefixes.length > 0 &&
    typeof b.effectiveFrom === 'string' &&
    /^\d{4}-\d{2}-\d{2}$/.test(b.effectiveFrom) &&
    (b.effectiveTo === undefined || b.effectiveTo === null || (typeof b.effectiveTo === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(b.effectiveTo))) &&
    (c === undefined ||
      (typeof c === 'object' &&
        c !== null &&
        (c.factsTrue === undefined || isStringArray(c.factsTrue)) &&
        (c.factsFalse === undefined || isStringArray(c.factsFalse)))) &&
    typeof b.description === 'string' &&
    Array.isArray(b.sources) &&
    b.sources.every(isSource)
  );
}

/** Parses an import-bans file's contents (`{ bans }` or an array); malformed entries are dropped. */
export function parseImportBans(raw: unknown): TariffImportBan[] {
  const list: unknown[] = Array.isArray(raw)
    ? raw
    : typeof raw === 'object' && raw !== null && Array.isArray((raw as { bans?: unknown }).bans)
    ? (raw as { bans: unknown[] }).bans
    : [];
  const out: TariffImportBan[] = [];
  for (const v of list) {
    if (isBan(v)) out.push(v);
    else console.warn(`[tariff-calculator] import-bans.json: malformed ban ${JSON.stringify(v).slice(0, 120)} — skipped`);
  }
  return out;
}

let cache: TariffImportBan[] | null = null;

/** Every import ban (empty list when there are none). */
export function loadImportBans(): TariffImportBan[] {
  if (!cache) cache = parseImportBans(importBansJson as unknown);
  return cache;
}
